// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        address actor,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // admissible domain: any caller, any values
        vm.prank(actor);
        bool ok;
        try c.setL1BlockValues(
            _number, _timestamp, _basefee, _hash,
            _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: setL1BlockValues never mutates basefee — it stays 0
        // whether the call reverts at the depositor gate or completes as a no-op.
        assertTrue(c.basefee() == 0);
        (ok); // silence unused warning
    }
}
